import unreal, os
proj_dir = unreal.Paths.convert_relative_path_to_full(unreal.Paths.project_dir())
h_path = os.path.join(proj_dir, "Source", "AesirWaveDefense", "AesirTuning.h")
cpp_path = os.path.join(proj_dir, "Source", "AesirWaveDefense", "AesirTuning.cpp")

h = open(h_path).read()
old_decl = "\t/** The tuning the running game uses (the wave game mode's), or nullptr. */\r\n\tstatic const UAesirTuning* Get(const UObject* WorldContext);\r\n"
assert old_decl in h, "decl not found"
new_decl = old_decl + "\r\n\t/** Set the damage falloff curve to full damage at 0, dropping to Value1 at Time1 (linear keys, clears existing keys). */\r\n\tUFUNCTION(BlueprintCallable, Category = \"Combat\")\r\n\tstatic void ConfigureDamageFalloffCurve(UCurveFloat* Curve, float Time1 = 2000.f, float Value1 = 0.5f);\r\n"
h = h.replace(old_decl, new_decl)
open(h_path, 'w').write(h)

cpp = open(cpp_path).read()
addition = '''
void UAesirTuning::ConfigureDamageFalloffCurve(UCurveFloat* Curve, float Time1, float Value1)
{
	if (!Curve)
	{
		return;
	}
	Curve->Modify();
	Curve->FloatCurve.Reset();
	const FKeyHandle Key0 = Curve->FloatCurve.AddKey(0.f, 1.f);
	const FKeyHandle Key1 = Curve->FloatCurve.AddKey(Time1, Value1);
	Curve->FloatCurve.SetKeyInterpMode(Key0, RCIM_Linear);
	Curve->FloatCurve.SetKeyInterpMode(Key1, RCIM_Linear);
	Curve->MarkPackageDirty();
}
'''
cpp = cpp.rstrip('\r\n') + '\r\n' + addition
open(cpp_path, 'w').write(cpp)
print("done")

