import unreal, os
proj_dir = unreal.Paths.convert_relative_path_to_full(unreal.Paths.project_dir())
src = os.path.join(proj_dir, "Source", "AesirWaveDefense")
hpath = os.path.join(src, "AesirHUD.h")
cpath = os.path.join(src, "AesirHUD.cpp")

with open(hpath, 'r', encoding='utf-8') as f:
    h = f.read()
with open(cpath, 'r', encoding='utf-8') as f:
    c = f.read()

# --- Header: add declaration ---
old_decl = "\tvoid DrawMissionObjectives();\r\n"
new_decl = "\tvoid DrawMissionObjectives();\r\n\t/** Always-on readout: live enemies-remaining count, bound directly to AAesirGameState::EnemiesRemaining. */\r\n\tvoid DrawEnemiesRemaining();\r\n"
assert old_decl in h, "decl anchor not found"
h2 = h.replace(old_decl, new_decl, 1)

# --- Cpp: add call in DrawHUD ---
old_call = "\tDrawWaveInstrument();\r\n\tDrawScore();\r\n"
new_call = "\tDrawWaveInstrument();\r\n\tDrawEnemiesRemaining();\r\n\tDrawScore();\r\n"
assert old_call in c, "call anchor not found"
c2 = c.replace(old_call, new_call, 1)

# --- Cpp: add function definition before DrawMissionObjectives definition ---
anchor = "// ---------------------------------------------------------------------------\r\n// Mission objective reads\r\n// ---------------------------------------------------------------------------\r\nvoid AAesirHUD::DrawMissionObjectives()"
assert anchor in c2, "def anchor not found"
func_def = '''// ---------------------------------------------------------------------------
// Always-on enemies-remaining readout — top-right instrument, bound live to
// AAesirGameState::EnemiesRemaining (replicated; ticks every DrawHUD).
// ---------------------------------------------------------------------------
void AAesirHUD::DrawEnemiesRemaining()
{
\tconst AAesirGameState* GS = GetWorld()->GetGameState<AAesirGameState>();
\tif (!GS)
\t{
\t\treturn;
\t}

\tconst FString Text = FString::Printf(TEXT("ENEMIES REMAINING: %02d"), GS->EnemiesRemaining);
\tconst FSlateFontInfo Font = AesirStyle::MonoBoldFont(18);
\tconst FVector2D Size = MeasureText(Text, Font);

\tconst float PadX = 16.f, PadY = 8.f;
\tconst float W = Size.X + PadX * 2.f;
\tconst float H = Size.Y + PadY * 2.f;
\tconst float X = Canvas->SizeX - W - 24.f;
\tconst float Y = 24.f;

\tDrawInstrumentPanel(X, Y, W, H, WithA(AesirPalette::PhosphorAmber(), 0.8f));
\tDrawTextItem(Text, X + PadX, Y + PadY, Font, AesirPalette::TextBone());
}

''' + anchor
c3 = c2.replace(anchor, func_def, 1)

with open(hpath, 'w', encoding='utf-8', newline='') as f:
    f.write(h2)
with open(cpath, 'w', encoding='utf-8', newline='') as f:
    f.write(c3)

print("done")

